  clusters=value['clusters'];ids=expected['ids'];seen=[];pred={}
  for index,group in enumerate(clusters):
   for ident in group:seen.append(ident);pred[ident]=index
  if len(seen)!=len(set(seen)) or set(seen)!=set(ids):return False
  true=expected['truth']
  def metrics(subset):
